import sys

def main():
    line = sys.stdin.readline().strip()
    if not line:
        return
    try:
        N = int(line)
    except ValueError:
        return

    if N <= 0:
        print(-1)
        return

    total = 0.0
    for i in range(1, N + 1):
        total += 1 / i

    print(f"{total:.4f}")

if __name__ == "__main__":
    main()
